    for (const l of bp.loads){ const h = 8 + 26 * l.kg / kmax; if (l.from != null) o += `<rect x="${X(l.from)}" y="${yB - 12}" width="${X(l.to) - X(l.from)}" height="6" fill="rgba(120,160,255,.35)"/>`; else o += `<line x1="${X(l.x)}" x2="${X(l.x)}" y1="${yB - 4 - h}" y2="${yB - 4}" stroke="#8fb4ff" stroke-width="1.5"/><path d="M${X(l.x) - 3},${yB - 9} L${X(l.x)},${yB - 3} L${X(l.x) + 3},${yB - 9}" fill="none" stroke="#8fb4ff"/>`; }
