    r.points.forEach((p, i) => { const x = X(p.alongMm / 1000), col = p.over || p.uplift ? COL.bad : p.capacityKg == null ? COL.unknown : COL.ok, src = s.points.find(q => q.id === p.id); o += `<line x1="${x}" x2="${x}" y1="${yB - 3}" y2="${src && src.leg ? yB + 3 : 30}" stroke="${col}" stroke-width="1.5"/>${src && src.leg ? `<rect x="${x - 5}" y="${yB + 3}" width="10" height="22" fill="none" stroke="${col}"/>` : `<path d="M${x},26 L${x - 4},34 L${x + 4},34 Z" fill="${col}"/>`}<text x="${x}" y="${src && src.leg ? yB + 36 : 18}" fill="${col}" text-anchor="middle">${p.uplift ? 'détendu' : f(p.designKg, 0) + ' kg'}</text><text x="${x - 24}" y="${src && src.leg ? yB + 36 : 18}" fill="#8a8d96" text-anchor="end">${i + 1} ·</text>`; });
